### Готовый скрипт нагона истории: `catchup_history.php`

Положите этот файл в корень проекта (или выполните как CLI-скрипт / вызовите через браузер). Он сам найдёт все файлы истории, прогонит 1-й уровень и в конце вызовет 2-й уровень.

```php
<?php

declare(strict_types=1);

// Подключаем необходимые файлы проекта
require_once __DIR__ . '/BaseHandler.php';
require_once __DIR__ . '/DictionaryService.php';

// Получаем PDO и AiService
$db = $GLOBALS['db'] ?? $GLOBALS['pdo'] ?? null;
$aiService = $GLOBALS['aiService'] ?? (class_exists('AiService') ? new AiService() : null);

if (!$db) {
    die("Ошибка: Нет подключения к БД (PDO null)\n");
}

if (!$aiService) {
    die("Ошибка: AiService недоступен\n");
}

// Задаем язык и пресет для обработки ('en' или 'pl')
$languageCode = 'en'; 
$presetName   = 'english_chronos'; // или нужная папка пресета

$dictService = new DictionaryService($db, $languageCode, $aiService);

// 1. Поиск всех файлов истории диалогов
$baseStorage = defined('STORAGE_PATH') 
    ? STORAGE_PATH 
    : (__DIR__ . '/presets_data/');

$sessionsDir = rtrim($baseStorage, '/\\') . '/' . $presetName . '/sessions/';

if (!is_dir($sessionsDir)) {
    die("Директория сессий не найдена: {$sessionsDir}\n");
}

$historyFiles = glob($sessionsDir . '*/chat_history.json');

echo "Найдено файлов истории: " . count($historyFiles) . "\n";

$allDialogRounds = [];

// Собираем все раунды из всех сессий
foreach ($historyFiles as $file) {
    $raw = file_get_contents($file);
    $history = json_decode($raw, true);
    if (!is_array($history)) continue;

    $totalMessages = count($history);
    for ($i = 0; $i < $totalMessages; $i++) {
        if (($history[$i]['role'] ?? '') === 'user') {
            $prevAiPrompt = ($i > 0 && ($history[$i - 1]['role'] ?? '') === 'assistant') 
                ? $history[$i - 1]['content'] 
                : 'No context';

            $allDialogRounds[] = [
                'ai_prompt'     => $prevAiPrompt,
                'user_response' => $history[$i]['content'] ?? ''
            ];
        }
    }
}

echo " Всего найдено раундов 'Пользователь -> ИИ': " . count($allDialogRounds) . "\n";

if (empty($allDialogRounds)) {
    die("История пуста, обработка не требуется.\n");
}

// ==========================================
// ЭТАП 1: Вызовы ИИ 1-го уровня (Пачками по 10 раундов)
// ==========================================
$batches = array_chunk($allDialogRounds, 10);
echo " Начинаем ЭТАП 1: Первичный анализ (" . count($batches) . " пачек по 10 раундов)...\n";

foreach ($batches as $index => $batch) {
    echo "  --> Обработка пачки " . ($index + 1) . " из " . count($batches) . "... ";

    // Вызываем приватный метод супервайзера через Reflection, чтобы прогнать пачку
    $reflection = new ReflectionClass($dictService);
    $method = $reflection->getMethod('runSupervisorCycle');
    $method->setAccessible(true);

    // Формируем структуру истории, которую ждет runSupervisorCycle
    $fakeRecentHistory = [];
    foreach ($batch as $round) {
        $fakeRecentHistory[] = ['role' => 'assistant', 'content' => $round['ai_prompt']];
        $fakeRecentHistory[] = ['role' => 'user',      'content' => $round['user_response']];
    }

    $method->invoke($dictService, $index + 1, $fakeRecentHistory);
    echo "ОК\n";

    // Небольшая пауза, чтобы не превысить rate-limit API
    usleep(500000); 
}

// ==========================================
// ЭТАП 2: Вызов ИИ 2-го уровня (Консолидация ошибок)
// ==========================================
echo "\n Начинаем ЭТАП 2: Системный анализ накопившихся ошибок и правил (ИИ 2 уровня)...\n";

$reflection = new ReflectionClass($dictService);
$methodLevel2 = $reflection->getMethod('analyzePersistentErrorsAndRules');
$methodLevel2->setAccessible(true);

$methodLevel2->invoke($dictService);

echo " ЭТАП 2 завершен! Грамматические правила, устойчивые слова и опечатки успешно сформированы.\n";

// Синхронизируем счетчик сообщений в user_meta
$stmtMeta = $db->prepare("
    INSERT INTO user_meta (language_code, user_message_count, supervisor_run_count)
    VALUES (:lang, :cnt, :runs)
    ON DUPLICATE KEY UPDATE user_message_count = :cnt, supervisor_run_count = :runs
");
$stmtMeta->execute([
    ':lang' => $languageCode,
    ':cnt'  => count($allDialogRounds),
    ':runs' => count($batches)
]);

echo "\n Всё готово! База словаря актуализирована под прошлую историю.\n";
```

